        action _num32_write {
                if (s->number64 <= UINT32_MAX) {
                        uint32_t num32 = htonl((uint32_t)s->number64);
                        memcpy(rdata_tail, &num32, 4);
                        rdata_tail += 4;
                } else {
                        WARN(ZS_NUMBER32_OVERFLOW);
                        fhold; fgoto err_line;
